interface Env { ASSETS: { fetch(request: Request): Promise<Response> }; DB: D1Database; TELEGRAM_BOT_TOKEN?: string; TELEGRAM_BOT_USERNAME?: string; MONETAG_POSTBACK_SECRET?: string; MONETAG_ZONE_ID?: string; ADMIN_SETUP_SECRET?: string; EDITORIAL_ADMIN_IDS?: string; }
const json=(data:unknown,status=200)=>new Response(JSON.stringify(data),{status,headers:{"content-type":"application/json; charset=utf-8","cache-control":"no-store","x-content-type-options":"nosniff","x-frame-options":"DENY","referrer-policy":"strict-origin-when-cross-origin","permissions-policy":"camera=(), microphone=(), geolocation=()","strict-transport-security":"max-age=31536000","x-permitted-cross-domain-policies":"none"}});
const encoder=new TextEncoder();
function safeEqual(a:string,b:string){if(a.length!==b.length)return false;let diff=0;for(let i=0;i<a.length;i++)diff|=a.charCodeAt(i)^b.charCodeAt(i);return diff===0;}
async function authenticatedUser(request:Request,env:Env):Promise<string|null>{
 if(!env.TELEGRAM_BOT_TOKEN)return null;
 const initData=request.headers.get("x-telegram-init-data")||"";
 const user=await verifyTelegramInitData(initData,env.TELEGRAM_BOT_TOKEN);
 return user?String(user.id):null;
}
const id=()=>crypto.randomUUID();

const bytesHex=(bytes:Uint8Array)=>Array.from(bytes,b=>b.toString(16).padStart(2,"0")).join("");
async function sha256Hex(value:string){return bytesHex(new Uint8Array(await crypto.subtle.digest("SHA-256",encoder.encode(value))));}
async function passwordHash(password:string,saltHex:string,iterations:number){if(!/^(?:[a-f0-9]{2}){16}$/i.test(saltHex))throw new Error("invalid salt");const saltBytes=Uint8Array.from(saltHex.match(/.{2}/g)!,v=>parseInt(v,16));const passwordBytes=encoder.encode(password);const saltBuffer=saltBytes.buffer.slice(saltBytes.byteOffset,saltBytes.byteOffset+saltBytes.byteLength) as ArrayBuffer;const passwordBuffer=passwordBytes.buffer.slice(passwordBytes.byteOffset,passwordBytes.byteOffset+passwordBytes.byteLength) as ArrayBuffer;let key:CryptoKey;try{key=await crypto.subtle.importKey("raw",passwordBuffer,{name:"PBKDF2"},false,["deriveBits"]);}catch(e){const x=e as Error;throw new Error("PBKDF2 importKey "+(x.name||"Error")+": "+(x.message||"failed"));}let bits:ArrayBuffer;try{bits=await crypto.subtle.deriveBits({name:"PBKDF2",hash:"SHA-256",salt:saltBuffer,iterations},key,256);}catch(e){const x=e as Error;throw new Error("PBKDF2 deriveBits "+(x.name||"Error")+": "+(x.message||"failed"));}return bytesHex(new Uint8Array(bits));}
function cookieValue(request:Request,name:string){const raw=request.headers.get("cookie")||"";for(const part of raw.split(";")){const [k,...v]=part.trim().split("=");if(k===name)return v.join("=");}return "";}
function sameOrigin(request:Request){const origin=request.headers.get("origin");return !!origin&&origin===new URL(request.url).origin;}
async function createAdminSession(env:Env,adminId:number){const random=new Uint8Array(32);crypto.getRandomValues(random);const token=bytesHex(random),tokenHash=await sha256Hex(token),expires=new Date(Date.now()+7*24*60*60*1000).toISOString();await env.DB.prepare("INSERT INTO admin_sessions (token_hash,admin_id,expires_at) VALUES (?,?,?)").bind(tokenHash,adminId,expires).run();return token;}
async function editorialAdmin(request:Request,env:Env):Promise<string|null>{const token=cookieValue(request,"st_admin");if(!token||token.length!==64)return null;try{const tokenHash=await sha256Hex(token);const session=await env.DB.prepare("SELECT s.admin_id FROM admin_sessions s JOIN admin_users a ON a.id=s.admin_id WHERE s.token_hash=? AND julianday(s.expires_at)>julianday('now')").bind(tokenHash).first<{admin_id:number}>();return session?String(session.admin_id):null;}catch{return null;}}
const textField=(v:unknown,max:number)=>typeof v==='string'?v.trim().slice(0,max):'';
const SOCIAL_TASK_HOSTS:Record<string,string[]>={telegram_channel:["t.me","telegram.me"],facebook_follow:["facebook.com","www.facebook.com","m.facebook.com","fb.com","www.fb.com"],whatsapp_community:["chat.whatsapp.com","whatsapp.com","www.whatsapp.com","wa.me"]};
function validateSocialTaskDestination(taskKey:string,value:unknown):{valid:boolean;url:string|null}{if(value===null||value==="")return {valid:true,url:null};if(typeof value!=="string"||value.length>2048)return {valid:false,url:null};const normalized=secureUrl(value);if(!normalized)return {valid:false,url:null};try{const parsed=new URL(normalized);if(parsed.username||parsed.password||parsed.port||!SOCIAL_TASK_HOSTS[taskKey]?.includes(parsed.hostname.toLowerCase()))return {valid:false,url:null};return {valid:true,url:normalized};}catch{return {valid:false,url:null};}}
async function qualifyReferral(telegramId:string,env:Env){
 await env.DB.prepare("UPDATE referrals SET qualified_at=CURRENT_TIMESTAMP WHERE invitee_user_id=? AND qualified_at IS NULL AND EXISTS(SELECT 1 FROM telegram_users WHERE telegram_user_id=? AND onboarding_step>=7 AND welcome_gift_claimed_at IS NOT NULL)").bind(telegramId,telegramId).run();
 const referral=await env.DB.prepare("SELECT inviter_user_id,COUNT(*) AS qualified FROM referrals WHERE inviter_user_id=(SELECT inviter_user_id FROM referrals WHERE invitee_user_id=?) AND qualified_at IS NOT NULL GROUP BY inviter_user_id").bind(telegramId).first<{inviter_user_id:string;qualified:number}>();
 if(referral&&Number(referral.qualified)>=3){
  const rewardKey="referral-milestone:"+referral.inviter_user_id+":3";
  await env.DB.batch([
   env.DB.prepare("INSERT OR IGNORE INTO wallets(user_id,ct_balance,sethis_balance) VALUES(?,0,0)").bind(referral.inviter_user_id),
   env.DB.prepare("INSERT OR IGNORE INTO wallet_ledger(id,user_id,token,amount,transaction_type,reference_id,idempotency_key,grant_source,grant_reason) VALUES(?,?,'SETHIS',500,'referral_reward',?,?,'referral','Three qualified referrals')").bind(id(),referral.inviter_user_id,rewardKey,rewardKey),
   env.DB.prepare("UPDATE wallets SET sethis_balance=sethis_balance+500,updated_at=CURRENT_TIMESTAMP WHERE user_id=? AND EXISTS(SELECT 1 FROM wallet_ledger WHERE idempotency_key=?) AND NOT EXISTS(SELECT 1 FROM referral_rewards WHERE ledger_key=?)").bind(referral.inviter_user_id,rewardKey,rewardKey),
   env.DB.prepare("INSERT OR IGNORE INTO referral_rewards(id,inviter_user_id,milestone,amount,ledger_key) VALUES(?,?,3,500,?)").bind(id(),referral.inviter_user_id,rewardKey),
   env.DB.prepare("INSERT OR IGNORE INTO notifications(id,user_id,type,title,body,reference_id,event_key) VALUES(?,?,'referral_reward','Referral milestone reached','Three invited friends completed onboarding. 500 SETHIS has been credited.',?,?)").bind(id(),referral.inviter_user_id,rewardKey,rewardKey)
  ]);
 }
}
async function telegramBotUsername(env:Env):Promise<string>{
 let username=env.TELEGRAM_BOT_USERNAME||"";
 if(!username&&env.TELEGRAM_BOT_TOKEN){
  try{const response=await fetch("https://api.telegram.org/bot"+env.TELEGRAM_BOT_TOKEN+"/getMe");const data=await response.json() as {ok?:boolean;result?:{username?:string}};if(data.ok&&data.result?.username)username=data.result.username;}catch{}
 }
 const normalized=username.replace(/^@/,"");return /^[A-Za-z0-9_]{5,32}$/.test(normalized)?normalized:"";
}


